<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { adminApi } from '../api/admin'
import { roleLabel } from '../constants/roles'
const users=ref<any[]>([]);const roles=ref<any[]>([]);const q=ref('');const role=ref('');const statusFilter=ref('active');const error=ref('');const page=ref(1);const pageSize=ref(10);const total=ref(0);const selected=ref<any>(null);const selectedRole=ref('');const detail=ref<any>(null)
const totalPages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)))
async function load(){try{const r=(await adminApi.users(q.value,role.value,statusFilter.value,pageSize.value,(page.value-1)*pageSize.value)).data.data;users.value=r.items;total.value=r.total;roles.value=(await adminApi.roles()).data.data}catch(e:any){error.value=e.response?.data?.detail||e.message}}
function search(){page.value=1;load()} function jump(){page.value=Math.min(Math.max(page.value,1),totalPages.value);load()} function changeSize(){page.value=1;load()}
async function toggleStatus(u:any){if(!window.confirm(u.status==='deleted'?'确认恢复该用户？':'确认软删除该用户？'))return;try{if(u.status==='deleted') await adminApi.restoreUser(u.id); else await adminApi.deleteUser(u.id);await load()}catch(e:any){error.value=e.response?.data?.detail||e.message}}
function openUserRole(u:any){selected.value=u;selectedRole.value=u.roles[0]||''} function openDetail(u:any){detail.value=u}
async function saveRole(){if(!selected.value)return;try{await adminApi.updateRoles(selected.value.id,[selectedRole.value]);await load();selected.value=null}catch(e:any){error.value=e.response?.data?.detail||e.message}}
onMounted(load)
</script>
<template><section class="admin-table-page"><div class="section-heading"><div><span class="eyebrow">ADMINISTRATION</span><h2>用户与权限</h2></div><span class="pill">系统管理员</span></div><p v-if="error" class="error">{{error}}</p><div class="admin-toolbar"><input v-model="q" placeholder="搜索用户名或姓名" @keyup.enter="search"/><select v-model="statusFilter" @change="search"><option value="active">正常</option><option value="deleted">已删除</option><option value="all">全部</option></select><select v-model="role" @change="search"><option value="">全部角色</option><option v-for="item in roles" :key="item.code" :value="item.code">{{item.name}}（{{item.code}}）</option></select><button class="button" @click="search">搜索</button><label>每页<select v-model.number="pageSize" @change="changeSize"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select>条</label></div><div class="admin-table-wrap wide-table"><table class="admin-table compact-table"><thead><tr><th>用户名</th><th>姓名</th><th>角色</th><th>状态</th><th>创建时间</th><th>修改时间</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td class="truncate-cell" :title="u.username">{{u.username}}</td><td class="truncate-cell" :title="u.display_name">{{u.display_name}}</td><td class="truncate-cell"><span v-for="r in u.roles" :key="r" class="table-tag">{{roleLabel(r)}}</span></td><td>{{u.status}}</td><td class="time-cell">{{u.created_at}}</td><td class="time-cell">{{u.updated_at}}</td><td class="action-cell"><button class="table-action" @click="openDetail(u)">详情</button><button v-if="u.status!=='deleted'" class="table-action" @click="openUserRole(u)">修改角色</button><button class="table-action danger" @click="toggleStatus(u)">{{u.status==='deleted'?'恢复':'删除'}}</button></td></tr><tr v-if="!users.length"><td colspan="7" class="table-empty">暂无用户</td></tr></tbody></table></div><div class="admin-pagination"><button :disabled="page<=1" @click="page--;load()">上一页</button><span>第 {{page}} / {{totalPages}} 页，共 {{total}} 条</span><input v-model.number="page" type="number" min="1" :max="totalPages" @keyup.enter="jump"/><button @click="jump">跳转</button><button :disabled="page>=totalPages" @click="page++;load()">下一页</button></div><div v-if="selected" class="admin-modal-backdrop" @click.self="selected=null"><div class="admin-modal"><h3>修改角色：{{selected.username}}</h3><select v-model="selectedRole"><option v-for="item in roles" :key="item.code" :value="item.code">{{item.name}}（{{item.code}}）</option></select><div class="action-row"><button class="button" @click="saveRole">保存</button><button class="text-button" @click="selected=null">取消</button></div></div></div><div v-if="detail" class="admin-modal-backdrop" @click.self="detail=null"><div class="admin-modal detail-modal"><div class="modal-header"><h3>用户详细信息</h3><button class="modal-close" @click="detail=null">×</button></div><dl class="detail-grid"><dt>用户名</dt><dd>{{detail.username}}</dd><dt>姓名</dt><dd>{{detail.display_name}}</dd><dt>角色</dt><dd>{{detail.roles?.map(roleLabel).join('、')}}</dd><dt>状态</dt><dd>{{detail.status}}</dd><dt>创建时间</dt><dd>{{detail.created_at}}</dd><dt>修改时间</dt><dd>{{detail.updated_at}}</dd><dt>删除时间</dt><dd>{{detail.deleted_at || '-'}}</dd><dt>用户 ID</dt><dd class="mono">{{detail.id}}</dd></dl></div></div></section></template>
